window.docContents[43].resolve({"/2___-Basic-notions-of-representation-theory/2___13___-Hilbert___s-third-problem/Section-2___13___-Hilbert___s-third-problem-___-heading/#Introduction-to-Representation-Theory--2___-Basic-notions-of-representation-theory--2___13___-Hilbert___s-third-problem--Section-2___13___-Hilbert___s-third-problem-___-heading":{"contents":"\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.13. Hilbert's third problem","header":"Section 2.13: Hilbert's third problem — heading","id":"/2___-Basic-notions-of-representation-theory/2___13___-Hilbert___s-third-problem/Section-2___13___-Hilbert___s-third-problem-___-heading/#Introduction-to-Representation-Theory--2___-Basic-notions-of-representation-theory--2___13___-Hilbert___s-third-problem--Section-2___13___-Hilbert___s-third-problem-___-heading"},"/2___-Basic-notions-of-representation-theory/2___16___-Problems-on-Lie-algebras/Section-2___16___-Problems-on-Lie-algebras-___-heading/#Chapter2___Discussion_2___16_heading":{"contents":"\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.16. Problems on Lie algebras\u0009Section 2.16: Problems on Lie algebras — heading","header":"Section 2.16: Problems on Lie algebras — heading","id":"/2___-Basic-notions-of-representation-theory/2___16___-Problems-on-Lie-algebras/Section-2___16___-Problems-on-Lie-algebras-___-heading/#Chapter2___Discussion_2___16_heading"},"/2___-Basic-notions-of-representation-theory/2___3___-Representations/Indecomposable-representation/#Chapter2___Definition2___3___8":{"contents":"Definition 2.3.8. A nonzero representation V of an algebra A is said to be indecomposable if it is not isomorphic to a direct sum of two nonzero representations.\n\n\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.3. Representations\u0009Indecomposable representation","header":"Indecomposable representation","id":"/2___-Basic-notions-of-representation-theory/2___3___-Representations/Indecomposable-representation/#Chapter2___Definition2___3___8"},"/3___-General-results-of-representation-theory/3___1___-Subrepresentations-in-semisimple-representations/Classification-of-subrepresentations-in-semisimple-representations/#Introduction-to-Representation-Theory--3___-General-results-of-representation-theory--3___1___-Subrepresentations-in-semisimple-representations--Classification-of-subrepresentations-in-semisimple-representations":{"contents":"\n\n","context":"Introduction to Representation Theory\u00093. General results of representation theory\u00093.1. Subrepresentations in semisimple representations","header":"Classification of subrepresentations in semisimple representations","id":"/3___-General-results-of-representation-theory/3___1___-Subrepresentations-in-semisimple-representations/Classification-of-subrepresentations-in-semisimple-representations/#Introduction-to-Representation-Theory--3___-General-results-of-representation-theory--3___1___-Subrepresentations-in-semisimple-representations--Classification-of-subrepresentations-in-semisimple-representations"},"/3___-General-results-of-representation-theory/3___5___-Finite-dimensional-algebras/Sum-of-squares-of-dimensions-of-irreducibles-bounded-by-dim-A/#Chapter3___Corollary3___5___5":{"contents":"Corollary 3.5.5. \\sum_i (\\dim V_i)^2 \\leq \\dim A, where the V_i's are the irreducible representations of A.\n\n\n\n\n\n","context":"Introduction to Representation Theory\u00093. General results of representation theory\u00093.5. Finite dimensional algebras\u0009Sum of squares of dimensions of irreducibles bounded by dim A","header":"Sum of squares of dimensions of irreducibles bounded by dim A","id":"/3___-General-results-of-representation-theory/3___5___-Finite-dimensional-algebras/Sum-of-squares-of-dimensions-of-irreducibles-bounded-by-dim-A/#Chapter3___Corollary3___5___5"},"/3___-General-results-of-representation-theory/3___9___-Problems/The-Clifford-algebra/#Chapter3___Problem3___9___5___formalization":{"contents":"\n\n\n\n","context":"Introduction to Representation Theory\u00093. General results of representation theory\u00093.9. Problems\u0009The Clifford algebra\u0009The Clifford algebra","header":"Formalization","id":"/3___-General-results-of-representation-theory/3___9___-Problems/The-Clifford-algebra/#Chapter3___Problem3___9___5___formalization"},"/4___-Representations-of-finite-groups___-Basic-results/4___10___-Frobenius-determinant/Setup-for-lemma-needed-in-proof/#Introduction-to-Representation-Theory--4___-Representations-of-finite-groups___-Basic-results--4___10___-Frobenius-determinant--Setup-for-lemma-needed-in-proof":{"contents":"\n\n","context":"Introduction to Representation Theory\u00094. Representations of finite groups: Basic results\u00094.10. Frobenius determinant","header":"Setup for lemma needed in proof","id":"/4___-Representations-of-finite-groups___-Basic-results/4___10___-Frobenius-determinant/Setup-for-lemma-needed-in-proof/#Introduction-to-Representation-Theory--4___-Representations-of-finite-groups___-Basic-results--4___10___-Frobenius-determinant--Setup-for-lemma-needed-in-proof"},"/4___-Representations-of-finite-groups___-Basic-results/4___11___-Historical-interlude___-Georg-Frobenius___s-___Principle-of-Horse-Trade___/Section-4___11___-Historical-interlude-___-Georg-Frobenius___s-Principle-of-Horse-Trade/#Chapter4___Discussion_4___11___heading-1":{"contents":"Ferdinand Georg Frobenius (1849--1917) studied at the famous Berlin University under both Karl Weierstrass and Leopold Kronecker, two great mathematicians who later became bitter opponents. Weierstrass considered Frobenius one of his brightest doctoral students and greased the wheels of his career by securing him a full professorship at the Zurich Polytechnikum. In Zurich Frobenius quickly got married, but the joys of happy matrimony did not prevent him from continuing productive research. Frobenius earned a high reputation for his\nstudies of elliptic and theta functions, determinant and matrix theory, and bilinear forms. Some fifteen years later, Kronecker's passing opened a vacant slot in Berlin, and Weierstrass got posthumous revenge on his old opponent by hiring his own student, Frobenius, for Kronecker's chair. In 1892 Frobenius left for Berlin, just four years before Einstein enrolled as a student in the Zurich Polytechnikum.\n\nPraised by his colleagues as \"a first-rate stylist\", who \"writes clearly and understandably without ever attempting to delude the reader with empty phrases\", Frobenius was soon elected to the prestigious Prussian Academy of Sciences [11, p. 38]. At this point, Frobenius began reevaluating his research interests. As he explained in his inaugural speech, the \"labyrinth of formulas\" in the theory of theta functions was having \"a withering effect upon the mathematical imagination\". He intended \"to overcome this paralysis of the mathematical creative powers by time and again seeking renewal at the fountain of youth of arithmetic\", i.e., number theory (quoted in [24, p. 220]). In his 40s, Frobenius indeed found this \"fountain of youth\" in \"arithmetic\", that is, in the theory of finite groups linked to the theory of numbers by Galois theory.\n\nIn 1896 Frobenius's comfortable life in Berlin was unceremoniously disrupted by several letters from Richard Dedekind, his old acquaintance and a predecessor at the Zurich Polytechnikum, now the dean of abstract algebra in Germany. After dealing with epistolary niceties and thanking Frobenius for brightening \"the African darkness of the theory of groups\", Dedekind shared some of his recent results on group theory, including his concept of the group determinant and the statement of his theorem about its factorization for abelian groups. Since Dedekind had not bothered to publish his work on the topic, Frobenius had never even heard of the group determinant, but he quickly grasped this concept and never let it go again. In his reply, Frobenius mildly chastised Dedekind for keeping back these \"extremely beautiful results from your friends and admirers\", and asked for more details. Dedekind then stumped his colleague with a \"conjectured theorem\" that the number of linear factors in\n\n","context":"Introduction to Representation Theory\u00094. Representations of finite groups: Basic results\u00094.11. Historical interlude: Georg Frobenius's \"Principle of Horse Trade\"\u0009Section 4.11: Historical interlude — Georg Frobenius's Principle of Horse Trade\u0009Section 4.11: Historical interlude — Georg Frobenius's Principle of Horse Trade","header":"4.11. Historical interlude: Georg Frobenius's \"Principle of Horse Trade\"","id":"/4___-Representations-of-finite-groups___-Basic-results/4___11___-Historical-interlude___-Georg-Frobenius___s-___Principle-of-Horse-Trade___/Section-4___11___-Historical-interlude-___-Georg-Frobenius___s-Principle-of-Horse-Trade/#Chapter4___Discussion_4___11___heading-1"},"/4___-Representations-of-finite-groups___-Basic-results/4___12___-Problems/Faithful-representations-contain-all-irreducibles-in-symmetric-powers/#Introduction-to-Representation-Theory--4___-Representations-of-finite-groups___-Basic-results--4___12___-Problems--Faithful-representations-contain-all-irreducibles-in-symmetric-powers--Faithful-representations-contain-all-irreducibles-in-symmetric-powers--Formalization--Supporting-declarations":{"contents":"Produces a nonzero equivariant map into a symmetric-power representation under the stated hypotheses.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter4/Problem4.12.10; role=supporting]\n\nConstructs a linear map from graded symmetric powers to functions on the group.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter4/Problem4.12.10; role=supporting]\n\n","context":"Introduction to Representation Theory\u00094. Representations of finite groups: Basic results\u00094.12. Problems\u0009Faithful representations contain all irreducibles in symmetric powers\u0009Faithful representations contain all irreducibles in symmetric powers\u0009Formalization","header":"Supporting declarations","id":"/4___-Representations-of-finite-groups___-Basic-results/4___12___-Problems/Faithful-representations-contain-all-irreducibles-in-symmetric-powers/#Introduction-to-Representation-Theory--4___-Representations-of-finite-groups___-Basic-results--4___12___-Problems--Faithful-representations-contain-all-irreducibles-in-symmetric-powers--Faithful-representations-contain-all-irreducibles-in-symmetric-powers--Formalization--Supporting-declarations"},"/4___-Representations-of-finite-groups___-Basic-results/4___1___-Maschke___s-theorem/Maschke___s-theorem/#Introduction-to-Representation-Theory--4___-Representations-of-finite-groups___-Basic-results--4___1___-Maschke___s-theorem--Maschke___s-theorem--Maschke___s-theorem--Formalization--Primary-declarations":{"contents":"The displayed finite-dimensional algebra conditions are equivalent under the stated hypotheses.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter3/Proposition3.5.8; role=primary]* Etingof et al., Introduction to Representation Theory [book-ref=Chapter4/Theorem4.1.1/Derived9; role=primary]\n\nApplying the displayed auxiliary map to the group-algebra element supported at g gives the action of g in each indexed component.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter4/Theorem4.1.1; role=primary]\n\nThe group algebra is equivalent to the family of endomorphism algebras of the indexed representations.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter4/Theorem4.1.1; role=primary]\n\nThere is a complete pairwise nonisomorphic family of simple representations whose dimensions index a coordinatewise group action isomorphic to the displayed auxiliary finite-dimensional representation.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter4/Proposition4.1.2/Derived3; role=supporting]* Etingof et al., Introduction to Representation Theory [book-ref=Chapter4/Theorem4.1.1; role=primary]\n\nThere is a complete pairwise nonisomorphic family of simple finite-dimensional representations whose endomorphism algebras form an algebra equivalent to the group algebra, and whose squared dimensions sum to the group order.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter4/Proposition4.1.2/Derived2; role=primary]* Etingof et al., Introduction to Representation Theory [book-ref=Chapter4/Theorem4.1.1; role=primary]\n\n","context":"Introduction to Representation Theory\u00094. Representations of finite groups: Basic results\u00094.1. Maschke's theorem\u0009Maschke's theorem\u0009Maschke's theorem\u0009Formalization","header":"Primary declarations","id":"/4___-Representations-of-finite-groups___-Basic-results/4___1___-Maschke___s-theorem/Maschke___s-theorem/#Introduction-to-Representation-Theory--4___-Representations-of-finite-groups___-Basic-results--4___1___-Maschke___s-theorem--Maschke___s-theorem--Maschke___s-theorem--Formalization--Primary-declarations"},"/5___-Representations-of-finite-groups___-Further-results/5___19___-Schur-Weyl-duality-for-___GL_LPAR_V_RPAR____/Schur-Weyl-decomposition-as-S_n-x-GL_LPAR_V_RPAR_-representation/#Chapter5___Corollary5___19___2___formalization":{"contents":"\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.19. Schur-Weyl duality for $GL(V)$\u0009Schur-Weyl decomposition as S_n x GL(V) representation\u0009Schur-Weyl decomposition as S_n x GL(V) representation","header":"Formalization","id":"/5___-Representations-of-finite-groups___-Further-results/5___19___-Schur-Weyl-duality-for-___GL_LPAR_V_RPAR____/Schur-Weyl-decomposition-as-S_n-x-GL_LPAR_V_RPAR_-representation/#Chapter5___Corollary5___19___2___formalization"},"/5___-Representations-of-finite-groups___-Further-results/5___1___-Frobenius-Schur-indicator/Quaternionic-representations-are-even-dimensional/#Introduction-to-Representation-Theory--5___-Representations-of-finite-groups___-Further-results--5___1___-Frobenius-Schur-indicator--Quaternionic-representations-are-even-dimensional--Quaternionic-representations-are-even-dimensional--Formalization--Primary-declarations":{"contents":"Under an auxiliary condition on a complex representation, its dimension is even.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Discussion_after_Definition5.1.1; role=primary]\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.1. Frobenius-Schur indicator\u0009Quaternionic representations are even-dimensional\u0009Quaternionic representations are even-dimensional\u0009Formalization","header":"Primary declarations","id":"/5___-Representations-of-finite-groups___-Further-results/5___1___-Frobenius-Schur-indicator/Quaternionic-representations-are-even-dimensional/#Introduction-to-Representation-Theory--5___-Representations-of-finite-groups___-Further-results--5___1___-Frobenius-Schur-indicator--Quaternionic-representations-are-even-dimensional--Quaternionic-representations-are-even-dimensional--Formalization--Primary-declarations"},"/5___-Representations-of-finite-groups___-Further-results/5___20___-Historical-interlude___-Hermann-Weyl-at-the-intersection-of-limitation-and-freedom/Hermann-Weyl-at-the-intersection-of-limitation-and-freedom/#Introduction-to-Representation-Theory--5___-Representations-of-finite-groups___-Further-results--5___20___-Historical-interlude___-Hermann-Weyl-at-the-intersection-of-limitation-and-freedom--Hermann-Weyl-at-the-intersection-of-limitation-and-freedom":{"contents":"\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.20. Historical interlude: Hermann Weyl at the intersection of limitation and freedom","header":"Hermann Weyl at the intersection of limitation and freedom","id":"/5___-Representations-of-finite-groups___-Further-results/5___20___-Historical-interlude___-Hermann-Weyl-at-the-intersection-of-limitation-and-freedom/Hermann-Weyl-at-the-intersection-of-limitation-and-freedom/#Introduction-to-Representation-Theory--5___-Representations-of-finite-groups___-Further-results--5___20___-Historical-interlude___-Hermann-Weyl-at-the-intersection-of-limitation-and-freedom--Hermann-Weyl-at-the-intersection-of-limitation-and-freedom"},"/5___-Representations-of-finite-groups___-Further-results/5___25___-Representations-of-___GL_2_LPAR____mathbb___F____q_RPAR____/5___25___4___-Complementary-series/#Chapter5___Discussion_5___25___4":{"contents":"5.25.4. Complementary series representations. Let \\mathbb{F}_{q^2} \\supset \\mathbb{F}_q be a quadratic extension \\mathbb{F}_q(\\sqrt{\\varepsilon}), \\varepsilon \\in \\mathbb{F}_q \\setminus \\mathbb{F}_q^2. We regard this as a 2-dimensional vector space over \\mathbb{F}_q; then G is the group of linear transformations of \\mathbb{F}_{q^2} over \\mathbb{F}_q. Let K \\subset G be the cyclic group of multiplications by elements of \\mathbb{F}_{q^2}^\\times,\n\nK = \\left\\{ \\begin{pmatrix} x & \\varepsilon y \\\\ y & x \\end{pmatrix} \\right\\}, \\qquad |K| = q^2 - 1.\n\nFor \\nu : K \\to \\mathbb{C}^\\times a homomorphism, let\n\nY_\\nu = \\operatorname{Ind}_K^G \\mathbb{C}_\\nu.\nThis representation, of course, is reducible. Let us compute its character, using the Frobenius formula. We get\n\n\\chi \\begin{pmatrix} x & 0 \\\\ 0 & x \\end{pmatrix} = q(q - 1)\\nu(x),\n\n\\chi(A) = 0 \\quad \\text{for } A \\text{ parabolic or hyperbolic},\n\n\\chi \\begin{pmatrix} x & \\varepsilon y \\\\ y & x \\end{pmatrix} = \\nu \\begin{pmatrix} x & \\varepsilon y \\\\ y & x \\end{pmatrix} + \\nu \\begin{pmatrix} x & \\varepsilon y \\\\ y & x \\end{pmatrix}^q.\n\nThe last assertion holds because if we regard the matrix as an element of \\mathbb{F}_{q^2}, conjugation is an automorphism of \\mathbb{F}_{q^2} over \\mathbb{F}_q, but the only nontrivial automorphism of \\mathbb{F}_{q^2} over \\mathbb{F}_q is the qth power map.\n\nWe thus have\n\n\\operatorname{Ind}_K^G \\mathbb{C}_{\\nu^q} \\cong \\operatorname{Ind}_K^G \\mathbb{C}_\\nu\n\nbecause they have the same character. Therefore, for \\nu^q \\neq \\nu we get \\frac{1}{2}q(q - 1) representations.\n\nNext, we look at the tensor product\n\nW_1 \\otimes V_{\\alpha, 1},\n\nwhere 1 is the trivial character and W_1 is defined as in the previous section. The character of this representation is\n\n\\chi \\begin{pmatrix} x & 0 \\\\ 0 & x \\end{pmatrix} = q(q + 1)\\alpha(x),\n\n\\chi(A) = 0 \\quad \\text{for } A \\text{ parabolic or elliptic},\n\n\\chi \\begin{pmatrix} x & 0 \\\\ 0 & y \\end{pmatrix} = \\alpha(x) + \\alpha(y).\n\nThus the \"virtual representation\"\n\nW_1 \\otimes V_{\\alpha, 1} - V_{\\alpha, 1} - \\operatorname{Ind}_K^G \\mathbb{C}_\\nu,\nwhere \\alpha is the restriction of \\nu to scalars, has the character\n\n\\chi \\begin{pmatrix} x & 0 \\\\ 0 & x \\end{pmatrix} = (q - 1)\\alpha(x),\n\n\\chi \\begin{pmatrix} x & 1 \\\\ 0 & x \\end{pmatrix} = -\\alpha(x),\n\n\\chi \\begin{pmatrix} x & 0 \\\\ 0 & y \\end{pmatrix} = 0,\n\n\\chi \\begin{pmatrix} x & \\varepsilon y \\\\ y & x \\end{pmatrix} = -\\nu \\begin{pmatrix} x & \\varepsilon y \\\\ y & x \\end{pmatrix} - \\nu^q \\begin{pmatrix} x & \\varepsilon y \\\\ y & x \\end{pmatrix}.\n\nIn all that follows, we will have \\nu^q \\neq \\nu.\n\nThe following two lemmas will establish that the inner product of this character with itself is equal to 1 and that its value at 1 is positive. As we know from Lemma 5.7.2, these two properties imply that it is the character of an irreducible representation of G.\n\n\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.25. Representations of $GL_2(\\mathbb{F}_q)$\u00095.25.4. Complementary series\u0009Section 5.25.4: Complementary series representations — setup and character computation","header":"Section 5.25.4: Complementary series representations — setup and character computation","id":"/5___-Representations-of-finite-groups___-Further-results/5___25___-Representations-of-___GL_2_LPAR____mathbb___F____q_RPAR____/5___25___4___-Complementary-series/#Chapter5___Discussion_5___25___4"},"/5___-Representations-of-finite-groups___-Further-results/5___25___-Representations-of-___GL_2_LPAR____mathbb___F____q_RPAR____/Section-5___25___-Representations-of-GL_2_LPAR_F_q_RPAR_/#Chapter5___Introduction_5___25___heading-1":{"contents":"","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.25. Representations of $GL_2(\\mathbb{F}_q)$\u0009Section 5.25: Representations of GL_2(F_q)\u0009Section 5.25: Representations of GL_2(F_q)","header":"5.25. Representations of  GL_2(\\mathbb{F}_q)","id":"/5___-Representations-of-finite-groups___-Further-results/5___25___-Representations-of-___GL_2_LPAR____mathbb___F____q_RPAR____/Section-5___25___-Representations-of-GL_2_LPAR_F_q_RPAR_/#Chapter5___Introduction_5___25___heading-1"},"/6___-Quiver-representations/6___3___-Indecomposable-representations-of-the-quiver-___D_4___/Section-6___3-heading-and-introduction/#Introduction-to-Representation-Theory--6___-Quiver-representations--6___3___-Indecomposable-representations-of-the-quiver-___D_4___--Section-6___3-heading-and-introduction":{"contents":"\n\n","context":"Introduction to Representation Theory\u00096. Quiver representations\u00096.3. Indecomposable representations of the quiver $D_4$","header":"Section 6.3 heading and introduction","id":"/6___-Quiver-representations/6___3___-Indecomposable-representations-of-the-quiver-___D_4___/Section-6___3-heading-and-introduction/#Introduction-to-Representation-Theory--6___-Quiver-representations--6___3___-Indecomposable-representations-of-the-quiver-___D_4___--Section-6___3-heading-and-introduction"},"/6___-Quiver-representations/6___8___-Proof-of-Gabriel___s-theorem/Corollary-6___8___4___-Existence-of-indecomposable-for-every-positive-root/#Chapter6___Corollary6___8___4___formalization":{"contents":"\n\n","context":"Introduction to Representation Theory\u00096. Quiver representations\u00096.8. Proof of Gabriel's theorem\u0009Corollary 6.8.4: Existence of indecomposable for every positive root\u0009Corollary 6.8.4: Existence of indecomposable for every positive root","header":"Formalization","id":"/6___-Quiver-representations/6___8___-Proof-of-Gabriel___s-theorem/Corollary-6___8___4___-Existence-of-indecomposable-for-every-positive-root/#Chapter6___Corollary6___8___4___formalization"},"/6___-Quiver-representations/6___9___-Problems/Section-6___9-heading___-Problems/#Introduction-to-Representation-Theory--6___-Quiver-representations--6___9___-Problems--Section-6___9-heading___-Problems":{"contents":"\n\n","context":"Introduction to Representation Theory\u00096. Quiver representations\u00096.9. Problems","header":"Section 6.9 heading: Problems","id":"/6___-Quiver-representations/6___9___-Problems/Section-6___9-heading___-Problems/#Introduction-to-Representation-Theory--6___-Quiver-representations--6___9___-Problems--Section-6___9-heading___-Problems"},"/7___-Introduction-to-categories/7___9___-Exact-functors/Section-7___9___-Exact-functors/#Introduction-to-Representation-Theory--7___-Introduction-to-categories--7___9___-Exact-functors--Section-7___9___-Exact-functors":{"contents":"\n\n","context":"Introduction to Representation Theory\u00097. Introduction to categories\u00097.9. Exact functors","header":"Section 7.9: Exact functors","id":"/7___-Introduction-to-categories/7___9___-Exact-functors/Section-7___9___-Exact-functors/#Introduction-to-Representation-Theory--7___-Introduction-to-categories--7___9___-Exact-functors--Section-7___9___-Exact-functors"}});